<?php require_admin();$section=(string)($_GET['section']??'sessions');?><h1>Manage website</h1><nav><a href="?page=manage&amp;section=sessions">Sessions</a><a href="?page=manage&amp;section=announcements">Announcements</a><a href="?page=manage&amp;section=media">Images</a><a href="?page=manage&amp;section=backup">Backup</a><a href="?page=manage&amp;section=email">Email status</a></nav>
<?php if($section==='sessions'):?><h2>Academic sessions</h2><?php foreach(db()->query('SELECT * FROM academic_sessions ORDER BY id DESC') as $s):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="edit_session"><input type="hidden" name="id" value="<?=e($s['id'])?>"><label>Name<input name="name" value="<?=e($s['name'])?>" maxlength="80" required></label><label>Start date<input type="date" name="start_date" value="<?=e($s['start_date'])?>"></label><label>End date<input type="date" name="end_date" value="<?=e($s['end_date'])?>"></label><label><input type="checkbox" name="is_active" <?=$s['is_active']?'checked':''?>>Active for new enquiries</label><button class="primary">Save session</button></form><?php endforeach;?><p>Deactivate old sessions to close intake. Existing enquiries keep their session.</p>
<?php elseif($section==='announcements'):?><h2>Announcements</h2><?php $rows=db()->query('SELECT * FROM announcements ORDER BY id DESC')->fetchAll();array_unshift($rows,['id'=>0,'title'=>'','body'=>'','is_published'=>0,'starts_at'=>null,'ends_at'=>null]);foreach($rows as $n):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_announcement"><input type="hidden" name="id" value="<?=e($n['id'])?>"><h3><?=$n['id']?'Edit announcement':'New announcement'?></h3><label>Title<input name="title" value="<?=e($n['title'])?>" required maxlength="160"></label><label>Body<textarea name="body" maxlength="5000"><?=e($n['body'])?></textarea></label><label><input type="checkbox" name="is_published" <?=$n['is_published']?'checked':''?>>Published</label><?php foreach(['starts_at'=>'Start','ends_at'=>'End']as$key=>$label):?><label><?=e($label)?> (<?=e(date_default_timezone_get())?>)<input type="datetime-local" name="<?=e($key)?>" value="<?=e($n[$key]?str_replace(' ','T',substr($n[$key],0,16)):'')?>"></label><?php endforeach;?><button class="primary">Save announcement</button></form><?php endforeach;?>
<?php elseif($section==='media'):?><h2>Website images</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="upload_image"><label>Image (JPEG, PNG or WebP, max 5 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label>Alt text<input name="alt_text" maxlength="250" required></label><button class="primary">Upload image</button></form><?php $images=db()->query('SELECT * FROM media ORDER BY id DESC')->fetchAll();foreach($images as$m):?><article><img class="media-preview" src="uploads/<?=e($m['stored_filename'])?>" alt="<?=e($m['alt_text'])?>"><p><?=e($m['original_filename'])?> · <?=e($m['alt_text'])?></p></article><?php endforeach;foreach(['logo','hero','about'] as $slot):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="assign_image"><input type="hidden" name="slot" value="<?=e($slot)?>"><label><?=e(ucfirst($slot))?> image<select name="media_id"><option value="0">Original default image</option><?php foreach($images as$m):?><option value="<?=e($m['id'])?>"><?=e($m['original_filename'])?></option><?php endforeach;?></select></label><button class="primary">Assign image</button></form><?php endforeach;?><p>Images are not deleted here, so published references cannot be broken accidentally.</p>
<?php elseif($section==='backup'):?><h2>Database backup</h2><p>Contains confidential parent/student records and password hashes. Store securely. Images require a separate copy of public/uploads. Restore only into a separate empty database using the recovery guide, never over live data without review.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="backup"><button class="primary">Create and download backup</button></form>
<?php elseif($section==='email'):?><h2>Email queue</h2><p>Pending messages are not sent until SMTP is configured and an operator runs the queue command. Sent means accepted by SMTP, not recipient delivery.</p><?php foreach(db()->query('SELECT id,notification_type,status,attempt_count,last_error_summary,created_at FROM notification_logs ORDER BY id DESC LIMIT 100')as$n):?><article><p>#<?=e($n['id'])?> <?=e($n['notification_type'])?> · <?=e($n['status'])?> · <?=e($n['attempt_count'])?> attempts · <?=e($n['created_at'])?></p><p><?=e($n['last_error_summary'])?></p></article><?php endforeach;endif;?>
